<script setup>import {ref,onMounted} from 'vue';import {api} from '../core';import PetCard from '../components/PetCard.vue';import Icon from '../components/Icon.vue';import State from '../components/State.vue';const pets=ref([]),loading=ref(true),error=ref('');async function load(){loading.value=true;error.value='';try{pets.value=(await api('/pets')).items.slice(0,4)}catch(e){error.value=e.message}finally{loading.value=false}}onMounted(load);</script>
<template><section class="home-hero"><div class="shell hero-grid"><div class="hero-copy"><span class="eyebrow pill"><Icon name="heart" :size="14"/> 一个家，一生的陪伴</span><h1>你在找一个伙伴，<br>它在等<span class="serif-accent">一个家。</span></h1><p>把偶然的相遇，变成长久的陪伴。<br>在寻爪，遇见那个刚刚好的小生命。</p><div class="row hero-actions"><RouterLink to="/pets" class="btn">遇见我的伙伴 <Icon name="arrow" :size="18"/></RouterLink><RouterLink to="/pets/new" class="quiet-link">我想帮助它找家 ↗</RouterLink></div><div class="hero-caption"><span class="little-paw">✦</span> 不止一次领养，是彼此的一生。</div></div><div class="hero-art"><img src="/assets/hero.webp" alt="依偎在一起等待新家的猫咪与狗狗"><div class="floating-note"><span>♡</span><div>你好，未来的家人。<small>我已经准备好爱你了</small></div></div><span class="art-mark">A LITTLE PAW.<br>A WHOLE LOT OF LOVE.</span></div></div></section><section class="promise-strip"><div class="shell"><span><Icon name="shield"/>清晰信息，安心了解</span><span><Icon name="user"/>直接沟通，认真选择</span><span><Icon name="check"/>双向确认，负责交接</span><span><Icon name="leaf"/>每份陪伴，都有归处</span></div></section><section class="shell section"><div class="section-heading"><div><p class="eyebrow">MEET YOUR NEW BEST FRIEND</p><h2>这些小可爱，正在等你</h2><p>也许你的新家人，就在下一次心动里。</p></div><RouterLink to="/pets" class="quiet-link">查看全部伙伴 <Icon name="arrow" :size="18"/></RouterLink></div><State :loading="loading" :error="error" :empty="!pets.length" text="还没有待领养伙伴，你可以发布第一条领养信息" @retry="load"/><div class="pet-grid" v-if="!loading&&!error"><PetCard v-for="p in pets" :key="p.id" :pet="p"/></div></section><section class="shell how-section"><div class="how-intro"><p class="eyebrow">A NEW CHAPTER, TOGETHER</p><h2>让相遇，<br>慢慢成为家人。</h2><RouterLink to="/pets" class="quiet-link">从认识它开始 <Icon name="arrow" :size="18"/></RouterLink></div><div v-for="(step,i) in [['发现你的伙伴','了解照片、地区与发布说明，找到适合自己的伙伴。'],['沟通与申请','登录后联系发布者，充分沟通，再提交领养申请。'],['双向确认，迎接回家','妥善安排交接，双方各自确认，共同开启新的生活。']]" :key="i" class="how-step"><span>0{{i+1}}</span><h3>{{step[0]}}</h3><p>{{step[1]}}</p></div></section><section class="shell shop-banner"><div><p class="eyebrow">LITTLE THINGS. BIG COMFORT.</p><h2>把爱，装进日常里。</h2><p>从第一口好粮，到最喜欢的玩具。<br>为新伙伴准备一点贴心的好物。</p><RouterLink to="/shop" class="btn">逛逛宠物好物 <Icon name="arrow" :size="18"/></RouterLink></div><img src="/assets/shop-hero.webp" alt="猫狗与日常宠物用品" loading="lazy"/></section></template>
